import { resolve } from "$app/paths";

export type ApiFile = "data.json" | "children.json" | "stats.json" | "download.json" | "data-version.json";

/** The files are generated by climbing-data-gen and served as static files, see vite.config.ts. */
export function apiUrl(slug: string, file: ApiFile): string {
  const base = resolve("/").replace(/\/$/, "");
  const path = slug ? `${slug.split("/").map(encodeURIComponent).join("/")}/` : "";
  return `${base}/api/world/${path}${file}`;
}
